-- =============================================================
-- FasalShield AI — fasalshield_db (MySQL / MariaDB, XAMPP)
-- Import: phpMyAdmin > Import > ye file choose karein, ya
-- app chalane par database khud bhi ban jata hai (db.py).
-- Disease data credit: PlantVillage research dataset (public
-- research) — ye data humne apne project me use kiya hai.
-- =============================================================
CREATE DATABASE IF NOT EXISTS fasalshield_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE fasalshield_db;

DROP TABLE IF EXISTS leaf_scans;
DROP TABLE IF EXISTS irrigation_logs;
DROP TABLE IF EXISTS local_guides;
DROP TABLE IF EXISTS risk_rules;
DROP TABLE IF EXISTS dept_contacts;
DROP TABLE IF EXISTS crop_calendar;
DROP TABLE IF EXISTS fertilizer_plans;
DROP TABLE IF EXISTS soil_factors;
DROP TABLE IF EXISTS crops;
DROP TABLE IF EXISTS diseases;

CREATE TABLE IF NOT EXISTS diseases (
        disease_id INT AUTO_INCREMENT PRIMARY KEY,
        label VARCHAR(160) NOT NULL UNIQUE,
        plant VARCHAR(80) NOT NULL,
        is_healthy TINYINT(1) NOT NULL DEFAULT 0,
        treatment_en TEXT, prevention_en TEXT,
        advice_ur TEXT, advice_sd TEXT, advice_ur_script TEXT
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS crops (
        crop_id INT AUTO_INCREMENT PRIMARY KEY,
        crop_name VARCHAR(80) NOT NULL UNIQUE,
        daily_litres_per_acre INT NOT NULL,
        kc DECIMAL(4,2) NOT NULL
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS soil_factors (
        soil_id INT AUTO_INCREMENT PRIMARY KEY,
        soil_name VARCHAR(80) NOT NULL UNIQUE,
        factor DECIMAL(4,2) NOT NULL
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS fertilizer_plans (
        plan_id INT AUTO_INCREMENT PRIMARY KEY,
        crop_name VARCHAR(80) NOT NULL UNIQUE,
        dap_bags DECIMAL(5,2) NULL, urea_bags DECIMAL(5,2) NULL, sop_bags DECIMAL(5,2) NULL,
        timing TEXT, per_plant_text TEXT
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS crop_calendar (
        cal_id INT AUTO_INCREMENT PRIMARY KEY,
        crop_name VARCHAR(80) NOT NULL UNIQUE,
        season VARCHAR(60), sowing TEXT, harvest TEXT, seed_rate TEXT,
        sowing_en TEXT, harvest_en TEXT, seed_en TEXT
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS dept_contacts (
        contact_id INT AUTO_INCREMENT PRIMARY KEY,
        name VARCHAR(160) NOT NULL, org VARCHAR(200), phone VARCHAR(40),
        address VARCHAR(200), timing VARCHAR(80), note TEXT
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS risk_rules (
        rule_id INT AUTO_INCREMENT PRIMARY KEY,
        crop_name VARCHAR(80) NOT NULL, disease_name VARCHAR(120) NOT NULL,
        kind VARCHAR(40), advice TEXT, advice_en TEXT
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS local_guides (
        guide_id INT AUTO_INCREMENT PRIMARY KEY,
        crop_name VARCHAR(80) NOT NULL, section_title VARCHAR(160) NOT NULL,
        section_text TEXT
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS leaf_scans (
        scan_id INT AUTO_INCREMENT PRIMARY KEY,
        disease_id INT NULL,
        label VARCHAR(160) NOT NULL,
        confidence DECIMAL(5,2) NOT NULL,
        severity_pct DECIMAL(5,2) NULL,
        scan_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        CONSTRAINT fk_scan_disease FOREIGN KEY (disease_id) REFERENCES diseases(disease_id)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS irrigation_logs (
        log_id INT AUTO_INCREMENT PRIMARY KEY,
        crop_name VARCHAR(80) NOT NULL, acres DECIMAL(6,2) NOT NULL,
        traditional_litres DECIMAL(14,2) NOT NULL, advised_litres DECIMAL(14,2) NOT NULL,
        saved_litres DECIMAL(14,2) NOT NULL,
        log_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

INSERT INTO diseases (label, plant, is_healthy, treatment_en, prevention_en, advice_ur, advice_sd, advice_ur_script) VALUES ('Apple Scab', 'Apple Scab', 0, 'Remove and destroy the badly infected leaves (do not compost them). Stop watering on the leaves - water only at the roots. If the disease is spreading fast, take this photo/result to your local agriculture shop or extension officer for a recommended spray for this exact disease.', 'Keep space between plants for air, water early morning at soil level, clean tools after use, and rotate crops next season.', 'Is patte mein bimari ke asaar hain. Kharab patte kaat kar door phenkein. Paani patto par nahi, jarr mein dein. Agar bimari barh rahi ho to qareebi agriculture officer ko ye result dikhayein.', 'هن پن ۾ بيماريءَ جا آثار آهن. خراب پن ڪٽي پري اڇلايو. پاڻي پنن تي نه، پاڙ ۾ ڏيو. جيڪڏهن بيماري وڌي رهي آهي ته ويجهي زرعي آفيسر کي هي نتيجو ڏيکاريو.', 'اس پتے میں بیماری کے آثار ہیں۔ خراب پتے کاٹ کر دور پھینک دیں۔ پانی پتوں پر نہیں، جڑ میں دیں۔ اگر بیماری بڑھ رہی ہو تو قریبی زرعی افسر کو یہ نتیجہ دکھائیں۔');
