INSERT INTO diseases (label, plant, is_healthy, treatment_en, prevention_en, advice_ur, advice_sd, advice_ur_script) VALUES ('Healthy Apple', 'Apple', 1, 'Good news - this plant looks healthy. Keep the same watering and fertiliser schedule, and keep checking leaves once a week for early spots.', 'Keep monitoring weekly - early detection is the best protection.', 'Mubarak! Ye poda sehatmand lag raha hai. Aisay hi paani aur khaad ka schedule jari rakhein, aur hafte mein ek dafa patto ko check karte rahein.', 'مبارڪون! هي ٻوٽو صحتمند لڳي ٿو. پاڻي ۽ ڀاڻ جو اهو ئي شيڊول جاري رکو، ۽ هفتي ۾ هڪ ڀيرو پن چيڪ ڪندا رهو.', 'مبارک ہو! یہ پودا صحت مند لگ رہا ہے۔ پانی اور کھاد کا یہی شیڈول جاری رکھیں، اور ہفتے میں ایک دفعہ پتوں کو چیک کرتے رہیں۔');
