INSERT INTO diseases (label, plant, is_healthy, treatment_en, prevention_en, advice_ur, advice_sd, advice_ur_script) VALUES ('Corn (Maize) with Common Rust', 'Corn (Maize)', 0, 'Usually light rust does not need spray. If pustules cover many leaves early, use a recommended fungicide advised by the extension officer.', 'Choose rust-resistant seed next season and avoid very late sowing.', 'Ye Makai ki Rust bimari hai. Halki ho to spray ki zarurat nahi. Agli dafa aisi beej lein jo is bimari se larr sake.', 'هن پن ۾ بيماريءَ جا آثار آهن. خراب پن ڪٽي پري اڇلايو. پاڻي پنن تي نه، پاڙ ۾ ڏيو. جيڪڏهن بيماري وڌي رهي آهي ته ويجهي زرعي آفيسر کي هي نتيجو ڏيکاريو.', 'یہ مکئی کی رسٹ بیماری ہے۔ ہلکی ہو تو اسپرے کی ضرورت نہیں۔ اگلی دفعہ ایسا بیج لیں جو اس بیماری سے لڑ سکے۔');
