INSERT INTO diseases (label, plant, is_healthy, treatment_en, prevention_en, advice_ur, advice_sd, advice_ur_script) VALUES ('Grape with Isariopsis Leaf Spot', 'Grape', 0, 'Remove and destroy the badly infected leaves (do not compost them). Stop watering on the leaves - water only at the roots. If the disease is spreading fast, take this photo/result to your local agriculture shop or extension officer for a recommended spray for this exact disease.', 'Keep space between plants for air, water early morning at soil level, clean tools after use, and rotate crops next season.', 'Is patte mein bimari ke asaar hain. Kharab patte kaat kar door phenkein. Paani patto par nahi, jarr mein dein. Agar bimari barh rahi ho to qareebi agriculture officer ko ye result dikhayein.', 'هن پن ۾ بيماريءَ جا آثار آهن. خراب پن ڪٽي پري اڇلايو. پاڻي پنن تي نه، پاڙ ۾ ڏيو. جيڪڏهن بيماري وڌي رهي آهي ته ويجهي زرعي آفيسر کي هي نتيجو ڏيکاريو.', 'اس پتے میں بیماری کے آثار ہیں۔ خراب پتے کاٹ کر دور پھینک دیں۔ پانی پتوں پر نہیں، جڑ میں دیں۔ اگر بیماری بڑھ رہی ہو تو قریبی زرعی افسر کو یہ نتیجہ دکھائیں۔');
