INSERT INTO diseases (label, plant, is_healthy, treatment_en, prevention_en, advice_ur, advice_sd, advice_ur_script) VALUES ('Healthy Bell Pepper Plant', 'Bell Pepper', 1, 'Good news - this plant looks healthy. Keep the same watering and fertiliser schedule, and keep checking leaves once a week for early spots.', 'Keep monitoring weekly - early detection is the best protection.', 'Mubarak! Ye poda sehatmand lag raha hai. Aisay hi paani aur khaad ka schedule jari rakhein, aur hafte mein ek dafa patto ko check karte rahein.', 'مبارڪون! هي ٻوٽو صحتمند لڳي ٿو. پاڻي ۽ ڀاڻ جو اهو ئي شيڊول جاري رکو، ۽ هفتي ۾ هڪ ڀيرو پن چيڪ ڪندا رهو.', 'مبارک ہو! یہ پودا صحت مند لگ رہا ہے۔ پانی اور کھاد کا یہی شیڈول جاری رکھیں، اور ہفتے میں ایک دفعہ پتوں کو چیک کرتے رہیں۔');
INSERT INTO diseases (label, plant, is_healthy, treatment_en, prevention_en, advice_ur, advice_sd, advice_ur_script) VALUES ('Potato with Early Blight', 'Potato', 0, 'Remove infected leaves, keep the crop well fed (weak plants catch it first), and apply a recommended fungicide if lesions increase.', 'Rotate crops, water at soil level, and avoid working in the field when leaves are wet.', 'Ye Aloo ki Early Blight hai. Kharab patte nikalein, fasal ko kamzor na honay dein, paani jarr mein dein.', 'هن پن ۾ بيماريءَ جا آثار آهن. خراب پن ڪٽي پري اڇلايو. پاڻي پنن تي نه، پاڙ ۾ ڏيو. جيڪڏهن بيماري وڌي رهي آهي ته ويجهي زرعي آفيسر کي هي نتيجو ڏيکاريو.', 'یہ آلو کی ارلی بلائٹ ہے۔ خراب پتے نکالیں، فصل کو کمزور نہ ہونے دیں، پانی جڑ میں دیں۔');
INSERT INTO diseases (label, plant, is_healthy, treatment_en, prevention_en, advice_ur, advice_sd, advice_ur_script) VALUES ('Potato with Late Blight', 'Potato', 0, 'Destroy infected plants and tubers immediately - do not leave them in the field. This is the most dangerous potato disease in wet weather.', 'Use certified seed, hill up soil well, and monitor daily when nights are cool and humid.', 'Ye Aloo ki Late Blight hai, bohat khatarnak hai. Kharab poday aur aalu foran zameen se nikalein taake bimari na phailay.', 'هن پن ۾ بيماريءَ جا آثار آهن. خراب پن ڪٽي پري اڇلايو. پاڻي پنن تي نه، پاڙ ۾ ڏيو. جيڪڏهن بيماري وڌي رهي آهي ته ويجهي زرعي آفيسر کي هي نتيجو ڏيکاريو.', 'یہ آلو کی لیٹ بلائٹ ہے، بہت خطرناک ہے۔ خراب پودے اور آلو فوراً زمین سے نکالیں تاکہ بیماری نہ پھیلے۔');
INSERT INTO diseases (label, plant, is_healthy, treatment_en, prevention_en, advice_ur, advice_sd, advice_ur_script) VALUES ('Healthy Potato Plant', 'Potato', 1, 'Good news - this plant looks healthy. Keep the same watering and fertiliser schedule, and keep checking leaves once a week for early spots.', 'Keep monitoring weekly - early detection is the best protection.', 'Mubarak! Ye poda sehatmand lag raha hai. Aisay hi paani aur khaad ka schedule jari rakhein, aur hafte mein ek dafa patto ko check karte rahein.', 'مبارڪون! هي ٻوٽو صحتمند لڳي ٿو. پاڻي ۽ ڀاڻ جو اهو ئي شيڊول جاري رکو، ۽ هفتي ۾ هڪ ڀيرو پن چيڪ ڪندا رهو.', 'مبارک ہو! یہ پودا صحت مند لگ رہا ہے۔ پانی اور کھاد کا یہی شیڈول جاری رکھیں، اور ہفتے میں ایک دفعہ پتوں کو چیک کرتے رہیں۔');
