INSERT INTO diseases (label, plant, is_healthy, treatment_en, prevention_en, advice_ur, advice_sd, advice_ur_script) VALUES ('Tomato with Bacterial Spot', 'Tomato', 0, 'Remove and destroy the badly infected leaves (do not compost them). Stop watering on the leaves - water only at the roots. If the disease is spreading fast, take this photo/result to your local agriculture shop or extension officer for a recommended spray for this exact disease.', 'Keep space between plants for air, water early morning at soil level, clean tools after use, and rotate crops next season.', 'Is patte mein bimari ke asaar hain. Kharab patte kaat kar door phenkein. Paani patto par nahi, jarr mein dein. Agar bimari barh rahi ho to qareebi agriculture officer ko ye result dikhayein.', 'هن پن ۾ بيماريءَ جا آثار آهن. خراب پن ڪٽي پري اڇلايو. پاڻي پنن تي نه، پاڙ ۾ ڏيو. جيڪڏهن بيماري وڌي رهي آهي ته ويجهي زرعي آفيسر کي هي نتيجو ڏيکاريو.', 'اس پتے میں بیماری کے آثار ہیں۔ خراب پتے کاٹ کر دور پھینک دیں۔ پانی پتوں پر نہیں، جڑ میں دیں۔ اگر بیماری بڑھ رہی ہو تو قریبی زرعی افسر کو یہ نتیجہ دکھائیں۔');
INSERT INTO diseases (label, plant, is_healthy, treatment_en, prevention_en, advice_ur, advice_sd, advice_ur_script) VALUES ('Tomato with Early Blight', 'Tomato', 0, 'Remove and destroy infected lower leaves. Do not compost them. Mulch around the plant so soil does not splash on leaves. Use a recommended fungicide from your local agri store if spots spread fast.', 'Water at the base, not on leaves. Give space between plants for air. Rotate tomato with another crop next season.', 'Ye Tamatar ki Early Blight bimari hai. Neeche wale kharab patte kaat kar zameen se door phenkein. Paani patto par nahi, jarr mein dein.', 'هن پن ۾ بيماريءَ جا آثار آهن. خراب پن ڪٽي پري اڇلايو. پاڻي پنن تي نه، پاڙ ۾ ڏيو. جيڪڏهن بيماري وڌي رهي آهي ته ويجهي زرعي آفيسر کي هي نتيجو ڏيکاريو.', 'یہ ٹماٹر کی ارلی بلائٹ بیماری ہے۔ نیچے والے خراب پتے کاٹ کر زمین سے دور پھینکیں۔ پانی پتوں پر نہیں، جڑ میں دیں۔');
INSERT INTO diseases (label, plant, is_healthy, treatment_en, prevention_en, advice_ur, advice_sd, advice_ur_script) VALUES ('Tomato with Late Blight', 'Tomato', 0, 'Remove badly infected plants at once - this spreads very fast in cool, wet weather. Avoid overhead watering. Use a recommended late-blight fungicide early if the disease is in your area.', 'Plant resistant varieties, keep good air flow, and check plants daily in rainy weather.', 'Ye Tamatar ki Late Blight hai, ye bohat tezi se phailti hai. Shadeed kharab poday foran nikalein. Barish ke mausam mein roz check karein.', 'هن پن ۾ بيماريءَ جا آثار آهن. خراب پن ڪٽي پري اڇلايو. پاڻي پنن تي نه، پاڙ ۾ ڏيو. جيڪڏهن بيماري وڌي رهي آهي ته ويجهي زرعي آفيسر کي هي نتيجو ڏيکاريو.', 'یہ ٹماٹر کی لیٹ بلائٹ ہے، یہ بہت تیزی سے پھیلتی ہے۔ شدید خراب پودے فوراً نکالیں۔ بارش کے موسم میں روز چیک کریں۔');
INSERT INTO diseases (label, plant, is_healthy, treatment_en, prevention_en, advice_ur, advice_sd, advice_ur_script) VALUES ('Tomato with Leaf Mold', 'Tomato', 0, 'Remove and destroy the badly infected leaves (do not compost them). Stop watering on the leaves - water only at the roots. If the disease is spreading fast, take this photo/result to your local agriculture shop or extension officer for a recommended spray for this exact disease.', 'Keep space between plants for air, water early morning at soil level, clean tools after use, and rotate crops next season.', 'Is patte mein bimari ke asaar hain. Kharab patte kaat kar door phenkein. Paani patto par nahi, jarr mein dein. Agar bimari barh rahi ho to qareebi agriculture officer ko ye result dikhayein.', 'هن پن ۾ بيماريءَ جا آثار آهن. خراب پن ڪٽي پري اڇلايو. پاڻي پنن تي نه، پاڙ ۾ ڏيو. جيڪڏهن بيماري وڌي رهي آهي ته ويجهي زرعي آفيسر کي هي نتيجو ڏيکاريو.', 'اس پتے میں بیماری کے آثار ہیں۔ خراب پتے کاٹ کر دور پھینک دیں۔ پانی پتوں پر نہیں، جڑ میں دیں۔ اگر بیماری بڑھ رہی ہو تو قریبی زرعی افسر کو یہ نتیجہ دکھائیں۔');
INSERT INTO diseases (label, plant, is_healthy, treatment_en, prevention_en, advice_ur, advice_sd, advice_ur_script) VALUES ('Tomato with Septoria Leaf Spot', 'Tomato', 0, 'Remove and destroy the badly infected leaves (do not compost them). Stop watering on the leaves - water only at the roots. If the disease is spreading fast, take this photo/result to your local agriculture shop or extension officer for a recommended spray for this exact disease.', 'Keep space between plants for air, water early morning at soil level, clean tools after use, and rotate crops next season.', 'Is patte mein bimari ke asaar hain. Kharab patte kaat kar door phenkein. Paani patto par nahi, jarr mein dein. Agar bimari barh rahi ho to qareebi agriculture officer ko ye result dikhayein.', 'هن پن ۾ بيماريءَ جا آثار آهن. خراب پن ڪٽي پري اڇلايو. پاڻي پنن تي نه، پاڙ ۾ ڏيو. جيڪڏهن بيماري وڌي رهي آهي ته ويجهي زرعي آفيسر کي هي نتيجو ڏيکاريو.', 'اس پتے میں بیماری کے آثار ہیں۔ خراب پتے کاٹ کر دور پھینک دیں۔ پانی پتوں پر نہیں، جڑ میں دیں۔ اگر بیماری بڑھ رہی ہو تو قریبی زرعی افسر کو یہ نتیجہ دکھائیں۔');
INSERT INTO diseases (label, plant, is_healthy, treatment_en, prevention_en, advice_ur, advice_sd, advice_ur_script) VALUES ('Tomato with Spider Mites or Two-spotted Spider Mite', 'Tomato', 0, 'Remove and destroy the badly infected leaves (do not compost them). Stop watering on the leaves - water only at the roots. If the disease is spreading fast, take this photo/result to your local agriculture shop or extension officer for a recommended spray for this exact disease.', 'Keep space between plants for air, water early morning at soil level, clean tools after use, and rotate crops next season.', 'Is patte mein bimari ke asaar hain. Kharab patte kaat kar door phenkein. Paani patto par nahi, jarr mein dein. Agar bimari barh rahi ho to qareebi agriculture officer ko ye result dikhayein.', 'هن پن ۾ بيماريءَ جا آثار آهن. خراب پن ڪٽي پري اڇلايو. پاڻي پنن تي نه، پاڙ ۾ ڏيو. جيڪڏهن بيماري وڌي رهي آهي ته ويجهي زرعي آفيسر کي هي نتيجو ڏيکاريو.', 'اس پتے میں بیماری کے آثار ہیں۔ خراب پتے کاٹ کر دور پھینک دیں۔ پانی پتوں پر نہیں، جڑ میں دیں۔ اگر بیماری بڑھ رہی ہو تو قریبی زرعی افسر کو یہ نتیجہ دکھائیں۔');
INSERT INTO diseases (label, plant, is_healthy, treatment_en, prevention_en, advice_ur, advice_sd, advice_ur_script) VALUES ('Tomato with Target Spot', 'Tomato', 0, 'Remove and destroy the badly infected leaves (do not compost them). Stop watering on the leaves - water only at the roots. If the disease is spreading fast, take this photo/result to your local agriculture shop or extension officer for a recommended spray for this exact disease.', 'Keep space between plants for air, water early morning at soil level, clean tools after use, and rotate crops next season.', 'Is patte mein bimari ke asaar hain. Kharab patte kaat kar door phenkein. Paani patto par nahi, jarr mein dein. Agar bimari barh rahi ho to qareebi agriculture officer ko ye result dikhayein.', 'هن پن ۾ بيماريءَ جا آثار آهن. خراب پن ڪٽي پري اڇلايو. پاڻي پنن تي نه، پاڙ ۾ ڏيو. جيڪڏهن بيماري وڌي رهي آهي ته ويجهي زرعي آفيسر کي هي نتيجو ڏيکاريو.', 'اس پتے میں بیماری کے آثار ہیں۔ خراب پتے کاٹ کر دور پھینک دیں۔ پانی پتوں پر نہیں، جڑ میں دیں۔ اگر بیماری بڑھ رہی ہو تو قریبی زرعی افسر کو یہ نتیجہ دکھائیں۔');
INSERT INTO diseases (label, plant, is_healthy, treatment_en, prevention_en, advice_ur, advice_sd, advice_ur_script) VALUES ('Tomato Yellow Leaf Curl Virus', 'Tomato Yellow Leaf Curl Virus', 0, 'There is no cure for virus-infected plants. Remove infected plants and control whitefly (the insect that spreads it) with recommended traps/spray.', 'Use virus-free nursery, yellow sticky traps for whitefly, and resistant varieties.', 'Ye virus ki bimari hai, iska ilaj nahi hota. Kharab poda nikalein aur safed makkhi ko control karein, wahi isay phailati hai.', 'هن پن ۾ بيماريءَ جا آثار آهن. خراب پن ڪٽي پري اڇلايو. پاڻي پنن تي نه، پاڙ ۾ ڏيو. جيڪڏهن بيماري وڌي رهي آهي ته ويجهي زرعي آفيسر کي هي نتيجو ڏيکاريو.', 'یہ وائرس کی بیماری ہے، اس کا علاج نہیں ہوتا۔ خراب پودا نکالیں اور سفید مکھی کو قابو کریں، وہی اسے پھیلاتی ہے۔');
INSERT INTO diseases (label, plant, is_healthy, treatment_en, prevention_en, advice_ur, advice_sd, advice_ur_script) VALUES ('Tomato Mosaic Virus', 'Tomato Mosaic Virus', 0, 'Remove and destroy the badly infected leaves (do not compost them). Stop watering on the leaves - water only at the roots. If the disease is spreading fast, take this photo/result to your local agriculture shop or extension officer for a recommended spray for this exact disease.', 'Keep space between plants for air, water early morning at soil level, clean tools after use, and rotate crops next season.', 'Is patte mein bimari ke asaar hain. Kharab patte kaat kar door phenkein. Paani patto par nahi, jarr mein dein. Agar bimari barh rahi ho to qareebi agriculture officer ko ye result dikhayein.', 'هن پن ۾ بيماريءَ جا آثار آهن. خراب پن ڪٽي پري اڇلايو. پاڻي پنن تي نه، پاڙ ۾ ڏيو. جيڪڏهن بيماري وڌي رهي آهي ته ويجهي زرعي آفيسر کي هي نتيجو ڏيکاريو.', 'اس پتے میں بیماری کے آثار ہیں۔ خراب پتے کاٹ کر دور پھینک دیں۔ پانی پتوں پر نہیں، جڑ میں دیں۔ اگر بیماری بڑھ رہی ہو تو قریبی زرعی افسر کو یہ نتیجہ دکھائیں۔');
INSERT INTO diseases (label, plant, is_healthy, treatment_en, prevention_en, advice_ur, advice_sd, advice_ur_script) VALUES ('Healthy Tomato Plant', 'Tomato', 1, 'Good news - this plant looks healthy. Keep the same watering and fertiliser schedule, and keep checking leaves once a week for early spots.', 'Keep monitoring weekly - early detection is the best protection.', 'Mubarak! Ye poda sehatmand lag raha hai. Aisay hi paani aur khaad ka schedule jari rakhein, aur hafte mein ek dafa patto ko check karte rahein.', 'مبارڪون! هي ٻوٽو صحتمند لڳي ٿو. پاڻي ۽ ڀاڻ جو اهو ئي شيڊول جاري رکو، ۽ هفتي ۾ هڪ ڀيرو پن چيڪ ڪندا رهو.', 'مبارک ہو! یہ پودا صحت مند لگ رہا ہے۔ پانی اور کھاد کا یہی شیڈول جاری رکھیں، اور ہفتے میں ایک دفعہ پتوں کو چیک کرتے رہیں۔');
INSERT INTO crops (crop_name, daily_litres_per_acre, kc) VALUES ('Cotton (Kapas)', 22000, 1.05);
INSERT INTO crops (crop_name, daily_litres_per_acre, kc) VALUES ('Banana (Kela)', 32000, 1.15);
INSERT INTO crops (crop_name, daily_litres_per_acre, kc) VALUES ('Dates (Khajoor)', 18000, 0.9);
INSERT INTO crops (crop_name, daily_litres_per_acre, kc) VALUES ('Wheat (Gandum)', 16000, 1.0);
INSERT INTO crops (crop_name, daily_litres_per_acre, kc) VALUES ('Tomato (Tamatar)', 20000, 1.05);
INSERT INTO crops (crop_name, daily_litres_per_acre, kc) VALUES ('Mango (Aam)', 19000, 0.85);
INSERT INTO crops (crop_name, daily_litres_per_acre, kc) VALUES ('Sugarcane (Ganna)', 30000, 1.2);
INSERT INTO crops (crop_name, daily_litres_per_acre, kc) VALUES ('Vegetables (Sabzi)', 18000, 1.0);
INSERT INTO soil_factors (soil_name, factor) VALUES ('Sandy (Retili)', 1.15);
INSERT INTO soil_factors (soil_name, factor) VALUES ('Loamy (Darmiyani)', 1.0);
INSERT INTO soil_factors (soil_name, factor) VALUES ('Clay (Chikni)', 0.85);
INSERT INTO fertilizer_plans (crop_name, dap_bags, urea_bags, sop_bags, timing) VALUES ('Wheat (Gandum)', 1.0, 2.0, 0.0, 'DAP sari boai ke waqt. Urea: aadhi pehle pani par, aadhi dusre pani par.');
INSERT INTO fertilizer_plans (crop_name, dap_bags, urea_bags, sop_bags, timing) VALUES ('Cotton (Kapas)', 1.0, 3.0, 1.0, 'DAP boai ke waqt. Urea 3 hisso me: 30, 60 aur 90 din par.');
INSERT INTO fertilizer_plans (crop_name, dap_bags, urea_bags, sop_bags, timing) VALUES ('Sugarcane (Ganna)', 2.0, 3.0, 1.0, 'DAP lagate waqt. Urea 2–3 hisso me pehle 4 mahino me.');
INSERT INTO fertilizer_plans (crop_name, dap_bags, urea_bags, sop_bags, timing) VALUES ('Tomato (Tamatar)', 2.0, 2.0, 1.0, 'DAP transplant ke waqt. Urea 2 hisso me: 3 hafte aur phool ane par.');
INSERT INTO fertilizer_plans (crop_name, dap_bags, urea_bags, sop_bags, timing) VALUES ('Vegetables (Sabzi)', 1.0, 1.5, 0.5, 'DAP lagate waqt. Urea chhote hisso me har katai ke baad.');
INSERT INTO fertilizer_plans (crop_name, per_plant_text) VALUES ('Banana (Kela)', 'Har poday par saal bhar me hisso me: Urea takreeban 300 g, DAP 150 g, SOP 300 g (aam sifarish).');
INSERT INTO fertilizer_plans (crop_name, per_plant_text) VALUES ('Dates (Khajoor)', 'Har baligh darakht par saal me 2 hisso me: Urea 1–1.5 kg, DAP 0.5–1 kg. Gobar ki khaad saal me ek dafa dein.');
INSERT INTO fertilizer_plans (crop_name, per_plant_text) VALUES ('Mango (Aam)', 'Har baligh darakht par: Urea 1–1.5 kg, DAP 0.5 kg, SOP 0.5 kg (darakht ki umar/size ke mutabiq).');
INSERT INTO crop_calendar (crop_name, season, sowing, harvest, seed_rate, sowing_en, harvest_en, seed_en) VALUES ('Wheat (Gandum)', 'Rabi', '7 November – 30 December (Upper Sindh / Khairpur). Behtreen waqt: 20 November se pehle — der se paidawar girti hai.', 'March – April', '50–60 kg per acre (Sindh Agriculture Dept)', '7 November - 30 December (Upper Sindh / Khairpur). Best time: before 20 November - late sowing reduces yield.', 'March - April', '50-60 kg per acre (Sindh Agriculture Dept)');
INSERT INTO crop_calendar (crop_name, season, sowing, harvest, seed_rate, sowing_en, harvest_en, seed_en) VALUES ('Cotton (Kapas)', 'Kharif', 'February – April (Sindh me kapas jaldi boi jati hai; kuch ilaqon me May ke shuru tak)', 'September – December (chunai kai dafa)', 'Takreeban 8–10 kg delinted seed per acre', 'February - April (cotton is sown early in Sindh; in some areas up to early May)', 'September - December (several pickings)', 'About 8-10 kg delinted seed per acre');
INSERT INTO crop_calendar (crop_name, season, sowing, harvest, seed_rate, sowing_en, harvest_en, seed_en) VALUES ('Sugarcane (Ganna)', 'Kharif / Saalaana', 'February – March aur September – October', 'November – March (crushing season)', 'Takreeban 70–90 maund setts per acre', 'February - March and September - October', 'November - March (crushing season)', 'About 70-90 maunds of setts per acre');
INSERT INTO crop_calendar (crop_name, season, sowing, harvest, seed_rate, sowing_en, harvest_en, seed_en) VALUES ('Tomato (Tamatar)', 'Rabi / Kharif dono', 'Nursery: July – August aur October – November; paneeri 3–4 hafte baad khet me', 'Lagane ke 60–90 din baad shuru', 'Paneeri (nursery) se lagta hai — takreeban 80–100 gram seed per acre nursery ke liye', 'Nursery: July - August and October - November; transplant after 3-4 weeks', 'Starts 60-90 days after transplanting', 'Grown from nursery seedlings - about 80-100 g seed per acre for the nursery');
INSERT INTO crop_calendar (crop_name, season, sowing, harvest, seed_rate, sowing_en, harvest_en, seed_en) VALUES ('Banana (Kela)', 'Saalaana (Perennial)', 'Sucker lagana: February – March aur August – September', 'Lagane ke 10–14 mahine baad pehla guccha; phir saal bhar', 'Sehatmand sucker (sword sucker) — bimari wale bagh se na lein', 'Planting suckers: February - March and August - September', 'First bunch 10-14 months after planting; then all year', 'Healthy sword suckers - never take suckers from a diseased garden');
INSERT INTO crop_calendar (crop_name, season, sowing, harvest, seed_rate, sowing_en, harvest_en, seed_en) VALUES ('Dates (Khajoor)', 'Saalaana (Perennial)', 'Offshoot lagana: February – March / August – September. Pollination: February – March', 'June – August (Khairpur ki mashhoor khajoor season)', 'Offshoot maa ke darakht se — wazan takreeban 10–15 kg wala offshoot behtar', 'Planting offshoots: February - March / August - September. Pollination: February - March', 'June - August (Khairpur\'s famous date season)', 'Offshoots from the mother tree - a 10-15 kg offshoot establishes best');
INSERT INTO crop_calendar (crop_name, season, sowing, harvest, seed_rate, sowing_en, harvest_en, seed_en) VALUES ('Mango (Aam)', 'Saalaana (Perennial)', 'Naye poday: February – March / July – August. Phool (boor): January – February', 'May – July', 'Grafted (qalami) poda lagayein — beej wala poda der aur ghair-yakeeni phal deta hai', 'New plants: February - March / July - August. Flowering: January - February', 'May - July', 'Plant grafted saplings - seed-grown trees fruit late and unpredictably');
INSERT INTO crop_calendar (crop_name, season, sowing, harvest, seed_rate, sowing_en, harvest_en, seed_en) VALUES ('Vegetables (Sabzi)', 'Dono season', 'Rabi sabzi: October – November. Kharif sabzi: February – March (sabzi ke mutabiq)', 'Sabzi ke mutabiq — aam tor par 45–90 din', 'Sabzi aur company ke packet par likhi miqdar ke mutabiq', 'Winter (Rabi) vegetables: October - November. Summer (Kharif) vegetables: February - March (depends on the vegetable)', 'Depends on the vegetable - usually 45-90 days', 'As printed on the seed packet for that vegetable');
INSERT INTO dept_contacts (name, org, phone, address, timing, note) VALUES ('Agriculture Extension Sindh — Helpline', 'Director General Agriculture Extension, Government of Sindh, Hyderabad', '0311-1646111', 'Shahbaz Building, Hyderabad, Sindh', 'Mon–Fri, 9 AM – 5 PM', 'Fasal ki bimari, khaad aur sarkari scheme ke liye pehla official number.');
INSERT INTO dept_contacts (name, org, phone, address, timing, note) VALUES ('Deputy Director Agriculture Extension — Khairpur', 'Agriculture Extension Department, District Khairpur Mirs', '', 'Station Road, Mirwah Colony, Khairpur Mirs', 'Office hours', 'Apne ilaqe ke Agriculture Officer / Field Assistant se milne ke liye district office.');
INSERT INTO dept_contacts (name, org, phone, address, timing, note) VALUES ('Sindh Agriculture University — Plant Experts', 'Sindh Agriculture University, Tandojam (Khairpur campus: KCAMS)', '', 'Tandojam / Old National Highway, Khairpur', 'Office hours', 'Mushkil ya naye case me university ke plant mahireen se tasdeeq ke liye.');
INSERT INTO risk_rules (crop_name, disease_name, kind, advice, advice_en) VALUES ('Tomato (Tamatar)', 'Late Blight', 'late_blight', 'Barish/nami me ye bimari bohat tezi se phailti hai. Patto ko roz check karein, pani jarr me dein, hawa ka guzar rakhein.', 'This disease spreads very fast in rain and humidity. Check leaves daily, water at the roots only, and keep air moving through the crop.');
INSERT INTO risk_rules (crop_name, disease_name, kind, advice, advice_en) VALUES ('Potato (Aalu)', 'Late Blight', 'late_blight', 'Thandi nami wali raato me risk zyada hota hai. Kharab poday foran nikalein taake bimari na phailay.', 'Risk rises on cool, humid nights. Remove infected plants at once so the disease does not spread.');
INSERT INTO risk_rules (crop_name, disease_name, kind, advice, advice_en) VALUES ('Tomato (Tamatar)', 'Early Blight', 'early_blight', 'Garam aur nami wale mausam me neeche wale patto par gol dhabbe bante hain. Kharab patte kaat dein.', 'In warm, humid weather, round spots appear on the lower leaves. Remove badly affected leaves.');
INSERT INTO risk_rules (crop_name, disease_name, kind, advice, advice_en) VALUES ('Corn (Maize / Makai)', 'Rust & Leaf Spots', 'fungal', 'Nami zyada ho to patto ke dhabbe barhte hain. Khet me hawa ka guzar aur faslo ka pher (rotation) madad karta hai.', 'In high humidity, leaf spots increase. Air flow in the field and crop rotation help.');
INSERT INTO risk_rules (crop_name, disease_name, kind, advice, advice_en) VALUES ('Cotton (Kapas)', 'Boll Rot / Paani Khara Hona', 'waterlog', 'Tez barish ke baad khet me pani khara na rehne dein — naali saaf rakhein, warna tinday sarte hain.', 'After heavy rain, do not let water stand in the field - keep the drains clear, otherwise the bolls rot.');
INSERT INTO risk_rules (crop_name, disease_name, kind, advice, advice_en) VALUES ('Cotton (Kapas)', 'Safed Makkhi / Jassid (keere)', 'heat_pest', 'Shadeed garmi me keere barhte hain. Patto ke neeche check karein; peeli chipchapi phansi (yellow sticky trap) lagayein.', 'In extreme heat, sucking pests increase. Check under the leaves; use yellow sticky traps.');
INSERT INTO risk_rules (crop_name, disease_name, kind, advice, advice_en) VALUES ('Banana (Kela)', 'Leaf Spot (Sigatoka type)', 'fungal', 'Nami me patto ke dhabbe barhte hain. Shadeed kharab patte kaat kar bagh se bahar karein. (Note: kele ke patte ki photo-detection hamare model me nahi — ye sirf mausam ki warning hai.)', 'In humidity, leaf spots increase. Cut badly affected leaves and remove them from the garden. (Note: banana leaf photo-detection is not in our model - this is weather advice only.)');
INSERT INTO risk_rules (crop_name, disease_name, kind, advice, advice_en) VALUES ('Any Crop (Aam)', 'Fungal Bimariyan (aam risk)', 'fungal', 'Lagatar barish aur zyada nami me aam fungal bimariyo ka risk barh jata hai. Spray barish se pehle na karein.', 'With continuous rain and high humidity, the general fungal disease risk rises. Do not spray just before rain.');
INSERT INTO local_guides (crop_name, section_title, section_text) VALUES ('Dates (Khajoor) 🌴', '💧 Paani', 'Garmi me har 7–10 din, sardi me 15–20 din baad pani dein (zameen ke mutabiq). Phal pakne ke qareeb pani kam kar dein — zyada pani se phal phat sakta hai.');
INSERT INTO local_guides (crop_name, section_title, section_text) VALUES ('Dates (Khajoor) 🌴', '🌱 Khaad', 'Baligh darakht: saal me 2 hisso me Urea 1–1.5 kg aur DAP 0.5–1 kg per darakht. Gobar ki gali-sarri khaad saal me ek dafa zaroor dein.');
INSERT INTO local_guides (crop_name, section_title, section_text) VALUES ('Dates (Khajoor) 🌴', '🐛 Aam Masla — Surkh Ghun (Red Palm Weevil)', 'Sab se khatarnak keera. Nishani: tanay me surakh, tanay se ras/gond nikalna, upar ke patte murjhana. Ye dikhe to khud spray par waqt zaya na karein — foran Agriculture Extension ko batayein (neeche contact).');
INSERT INTO local_guides (crop_name, section_title, section_text) VALUES ('Dates (Khajoor) 🌴', '🍂 Aam Masla — Phal Sarna', 'Barish/nami ke mausam me phal sarta hai. Bagh me hawa ka guzar rakhein, kharab phal gira kar zameen se uthayein, phal ko zameen se lagne na dein.');
INSERT INTO local_guides (crop_name, section_title, section_text) VALUES ('Dates (Khajoor) 🌴', '🔍 Check Kab Karein', 'Har mahine tanay (khaas kar upar wala hissa) aur phal ka jaiza lein. Pollination February–March me waqt par karein — der se pollination = kam phal.');
INSERT INTO local_guides (crop_name, section_title, section_text) VALUES ('Banana (Kela) 🍌', '💧 Paani', 'Kela pani zyada mangta hai: garmi me 5–7 din baad pani, zameen me nami bani rahe — lekin pani khara bilkul na ho, jarr sar jati hai.');
INSERT INTO local_guides (crop_name, section_title, section_text) VALUES ('Banana (Kela) 🍌', '🌱 Khaad', 'Har poday par saal bhar me hisso me: Urea takreeban 300 g, DAP 150 g, SOP 300 g. Ek dafa me sari khaad na dein.');
INSERT INTO local_guides (crop_name, section_title, section_text) VALUES ('Banana (Kela) 🍌', '🦠 Aam Masla — Bunchy Top Virus', 'Nishani: poda chota reh jana, naye patte tang aur ikatthe (guccha numa) nikalna. Is virus ka ilaj nahi — mutasir poda nikaal kar zameen se bahar karein, aur hamesha sehatmand sucker lagayein.');
INSERT INTO local_guides (crop_name, section_title, section_text) VALUES ('Banana (Kela) 🍌', '🍂 Aam Masla — Patto ke Dhabbe', 'Nami wale mausam me patto par dhabbe barhte hain. Shadeed kharab patte kaat kar bagh se bahar karein, podo ke darmiyan hawa ka faasla rakhein.');
INSERT INTO local_guides (crop_name, section_title, section_text) VALUES ('Banana (Kela) 🍌', '🌬️ Hawa se Bachao', 'Tez hawa kele ko gira deti hai. Guccha ane par poday ko bans ka sahara dein, aur bagh ke kinare hawa-rok (windbreak) darakht lagayein.');

